import { withPostgresTransaction } from '../../core/database/transaction.js';
import { AppError } from '../../core/errors/app-error.js';
import type { AuthContext } from '../../core/security/auth-context.js';
import { checkContent } from '../content-control/content-control.service.js';
import type { CreateChapterInput, UpdateChapterInput } from './chapters.schemas.js';
import {
  createChapter as createChapterRow,
  findChapterById,
  getNextChapterNumber,
  listChaptersByNovelId,
  publishChapter,
  submitChapterForPublish,
  updateChapterMetadata,
  touchChapterUpdatedAt,
  updateChapterPricing
} from './chapters.repository.js';
import { findDraftChapterByChapterId, upsertDraftChapter } from './draft-chapters.repository.js';
import { getNovel } from './novels.service.js';

function countWords(content: string) {
  return content.trim().split(/\s+/).filter(Boolean).length;
}

function assertOwner(resource: { authorId: string }, auth: AuthContext) {
  if (auth.role === 'ADMIN') {
    return;
  }

  if (resource.authorId !== auth.userId) {
    throw new AppError(403, 'CONTENT_005', 'Content ownership required');
  }
}

function assertPremiumPricing(input: { isVip: boolean; priceCoins: number }) {
  if (input.isVip && input.priceCoins <= 0) {
    throw new AppError(400, 'VALIDATION_001', 'Premium chapter requires priceCoins greater than 0');
  }

  if (!input.isVip && input.priceCoins !== 0) {
    throw new AppError(400, 'VALIDATION_001', 'Free chapter requires priceCoins to be 0');
  }
}

export async function createChapter(auth: AuthContext, novelId: string, input: CreateChapterInput) {
  const novel = await getNovel(novelId);
  assertOwner(novel, auth);
  assertPremiumPricing({ isVip: input.isVip, priceCoins: input.priceCoins });

  const wordCount = countWords(input.content);
  const chapter = await withPostgresTransaction(async (client) => {
    const chapterNumber = await getNextChapterNumber(client, novelId);

    return createChapterRow(client, {
      novelId,
      title: input.title,
      chapterNumber,
      wordCount,
      isVip: input.isVip,
      priceCoins: input.priceCoins
    });
  });

  const draft = await upsertDraftChapter({
    chapterId: chapter.chapterId,
    novelId,
    authorId: auth.userId,
    title: input.title,
    content: input.content,
    wordCount,
    autosave: false
  });

  return {
    ...chapter,
    draftVersion: draft?.version ?? 1
  };
}

export async function listChapters(novelId: string) {
  await getNovel(novelId);
  return listChaptersByNovelId(novelId);
}

export async function getChapter(chapterId: string) {
  const chapter = await findChapterById(chapterId);

  if (!chapter) {
    throw new AppError(404, 'CONTENT_001', 'Content not found');
  }

  const draft = await findDraftChapterByChapterId(chapterId);

  return {
    ...chapter,
    draft: draft
      ? {
          title: draft.title,
          content: draft.content,
          wordCount: draft.wordCount,
          version: draft.version,
          autosave: draft.autosave,
          updatedAt: draft.updatedAt
        }
      : null
  };
}

export async function updateChapter(auth: AuthContext, chapterId: string, input: UpdateChapterInput) {
  const chapter = await findChapterById(chapterId);

  if (!chapter) {
    throw new AppError(404, 'CONTENT_001', 'Content not found');
  }

  const novel = await getNovel(chapter.novelId);
  assertOwner(novel, auth);

  const isPublishedPricingOnlyUpdate =
    chapter.status === 'PUBLISHED' &&
    (input.isVip !== undefined || input.priceCoins !== undefined) &&
    input.title === undefined &&
    input.content === undefined;

  if (!['DRAFT', 'REJECTED', 'PENDING_MODERATION', 'PUBLISHED'].includes(chapter.status) && !isPublishedPricingOnlyUpdate) {
    throw new AppError(409, 'CONTENT_004', 'Invalid content state');
  }

  const nextTitle = input.title ?? chapter.title;
  const existingDraft = await findDraftChapterByChapterId(chapterId);
  const nextContent = input.content ?? existingDraft?.content ?? chapter.content ?? '';
  const wordCount = nextContent ? countWords(nextContent) : chapter.wordCount;
  const nextIsVip = input.isVip ?? chapter.isVip;
  const nextPriceCoins = input.priceCoins ?? (nextIsVip ? chapter.priceCoins : 0);
  assertPremiumPricing({ isVip: nextIsVip, priceCoins: nextPriceCoins });

  const isPublishedDraftUpdate =
    chapter.status === 'PUBLISHED' && (input.title !== undefined || input.content !== undefined) && !isPublishedPricingOnlyUpdate;

  let updatedChapter;

  if (isPublishedDraftUpdate) {
    updatedChapter =
      input.isVip !== undefined || input.priceCoins !== undefined
        ? await updateChapterPricing(chapterId, {
            isVip: nextIsVip,
            priceCoins: nextPriceCoins
          })
        : chapter;
  } else if (isPublishedPricingOnlyUpdate) {
    updatedChapter = await updateChapterPricing(chapterId, {
      isVip: nextIsVip,
      priceCoins: nextPriceCoins
    });
  } else {
    updatedChapter = await updateChapterMetadata(chapterId, {
      title: input.title,
      wordCount,
      isVip: nextIsVip,
      priceCoins: nextPriceCoins
    });
  }

  if (!updatedChapter) {
    throw new AppError(409, 'CONTENT_004', 'Invalid content state');
  }

  let draft = existingDraft;

  if (input.title !== undefined || input.content !== undefined) {
    if (!nextContent) {
      throw new AppError(409, 'CONTENT_004', 'Invalid content state');
    }

    draft = await upsertDraftChapter({
      chapterId,
      novelId: chapter.novelId,
      authorId: auth.userId,
      title: nextTitle,
      content: nextContent,
      wordCount,
      autosave: input.autosave
    });
    if (isPublishedDraftUpdate) await touchChapterUpdatedAt(chapterId);
  }

  return {
    ...updatedChapter,
    draftVersion: draft?.version ?? null
  };
}

export async function submitChapterPublish(auth: AuthContext, chapterId: string) {
  const chapter = await findChapterById(chapterId);

  if (!chapter) {
    throw new AppError(404, 'CONTENT_001', 'Content not found');
  }

  const novel = await getNovel(chapter.novelId);
  assertOwner(novel, auth);

  if (!['DRAFT', 'REJECTED', 'PENDING_MODERATION', 'PUBLISHED'].includes(chapter.status)) {
    throw new AppError(409, 'CONTENT_004', 'Invalid content state');
  }

  const draft = await findDraftChapterByChapterId(chapterId);
  const publishTitle = draft?.title ?? chapter.title;
  const publishContent = draft?.content ?? chapter.content;
  const publishWordCount = draft?.wordCount ?? chapter.wordCount;

  if (!publishContent) {
    throw new AppError(409, 'CONTENT_004', 'Invalid content state');
  }

  const moderation = await checkContent({
    targetType: 'CHAPTER',
    targetId: chapter.chapterId,
    content: `${publishTitle}\n\n${publishContent}`,
    submittedBy: auth.userId
  });

  if (!moderation.moderationRequired) {
    const publishedChapter = await publishChapter(chapterId, {
      title: publishTitle,
      content: publishContent,
      wordCount: publishWordCount
    });

    if (!publishedChapter) {
      throw new AppError(409, 'CONTENT_004', 'Invalid content state');
    }

    return {
      chapterId: publishedChapter.chapterId,
      status: publishedChapter.status,
      moderationRequired: false,
      moderationReviewId: null
    };
  }

  const updatedChapter = chapter.status === 'PENDING_MODERATION' ? chapter : await submitChapterForPublish(chapterId);
  if (!updatedChapter) {
    throw new AppError(409, 'CONTENT_004', 'Invalid content state');
  }

  return {
    chapterId: updatedChapter.chapterId,
    status: updatedChapter.status,
    moderationRequired: true,
    moderationReviewId: moderation.moderationReviewId
  };
}

import { z } from 'zod';

export const novelIdParamSchema = z.object({
  params: z.object({
    novelId: z.string().uuid()
  })
});

export const chapterIdParamSchema = z.object({
  params: z.object({
    chapterId: z.string().uuid()
  })
});

export const createChapterSchema = z.object({
  params: novelIdParamSchema.shape.params,
  body: z.object({
    title: z.string().min(1).max(100),
    content: z.string().default(''),
    isVip: z.boolean().default(false),
    priceCoins: z.number().int().min(0).default(0)
  })
});

export const updateChapterSchema = z.object({
  params: chapterIdParamSchema.shape.params,
  body: z.object({
    title: z.string().min(1).max(100).optional(),
    content: z.string().optional(),
    isVip: z.boolean().optional(),
    priceCoins: z.number().int().min(0).optional(),
    autosave: z.boolean().default(false)
  })
});

export type CreateChapterInput = z.infer<typeof createChapterSchema>['body'];
export type UpdateChapterInput = z.infer<typeof updateChapterSchema>['body'];

import { ObjectId } from 'mongodb';
import { getMongoDatabase } from '../../core/database/mongo.js';

const collectionName = 'draft_chapters';

export type DraftChapterDocument = {
  _id?: ObjectId;
  chapterId: string;
  novelId: string;
  authorId: string;
  title: string;
  content: string;
  wordCount: number;
  version: number;
  autosave: boolean;
  lastAcceptedRevisionId?: string | null;
  lastAcceptedAt?: Date | null;
  createdAt: Date;
  updatedAt: Date;
  deletedAt?: Date | null;
  deletionReason?: string | null;
  restoredAt?: Date | null;
};

function collection() {
  return getMongoDatabase().collection<DraftChapterDocument>(collectionName);
}

export async function ensureDraftChapterIndexes() {
  await collection().createIndex({ chapterId: 1, updatedAt: -1 });
  await collection().createIndex({ novelId: 1, authorId: 1 });
  await collection().createIndex({ chapterId: 1 }, { unique: true });
}

export async function upsertDraftChapter(input: {
  chapterId: string;
  novelId: string;
  authorId: string;
  title: string;
  content: string;
  wordCount: number;
  autosave: boolean;
  lastAcceptedRevisionId?: string | null;
}) {
  const now = new Date();

  await collection().updateOne(
    { chapterId: input.chapterId },
    {
      $set: {
        novelId: input.novelId,
        authorId: input.authorId,
        title: input.title,
        content: input.content,
        wordCount: input.wordCount,
        autosave: input.autosave,
        ...(input.lastAcceptedRevisionId !== undefined
          ? { lastAcceptedRevisionId: input.lastAcceptedRevisionId, lastAcceptedAt: now }
          : {}),
        deletedAt: null,
        deletionReason: null,
        updatedAt: now
      },
      $setOnInsert: {
        chapterId: input.chapterId,
        createdAt: now
      },
      $inc: {
        version: 1
      }
    },
    { upsert: true }
  );

  return findDraftChapterByChapterId(input.chapterId);
}

export async function syncDraftFromRevisionConditional(input: {
  chapterId: string;
  revisionId: string;
  title?: string;
  content: string;
  wordCount: number;
  acceptTimestamp: Date;
  novelId?: string;
  authorId?: string;
}): Promise<{ status: 'synced' | 'skipped_newer_draft'; draft?: DraftChapterDocument | null }> {
  const now = new Date();
  const existing = await collection().findOne({ chapterId: input.chapterId, deletedAt: null });
  if (existing) {
    if (existing.updatedAt && existing.updatedAt > input.acceptTimestamp) {
      return { status: 'skipped_newer_draft', draft: existing };
    }
  } else {
    // If draft does not exist yet, atomically create it with trusted ownership
    const newDraft: DraftChapterDocument = {
      novelId: input.novelId ?? '',
      chapterId: input.chapterId,
      authorId: input.authorId ?? '',
      title: input.title ?? 'Chương mới',
      content: input.content,
      wordCount: input.wordCount,
      version: 1,
      autosave: false,
      lastAcceptedRevisionId: input.revisionId,
      lastAcceptedAt: input.acceptTimestamp,
      createdAt: now,
      updatedAt: now,
      deletedAt: null
    };
    try {
      await collection().insertOne(newDraft as any);
      return { status: 'synced', draft: newDraft };
    } catch (err: any) {
      if (err?.code === 11000 || String(err?.message).includes('E11000')) {
        const found = await collection().findOne({ chapterId: input.chapterId, deletedAt: null });
        if (found && found.updatedAt && found.updatedAt > input.acceptTimestamp) {
          return { status: 'skipped_newer_draft', draft: found };
        }
      } else {
        throw err;
      }
    }
  }

  const result = await collection().updateOne(
    {
      chapterId: input.chapterId,
      $or: [
        { updatedAt: { $lte: input.acceptTimestamp } },
        { updatedAt: { $exists: false } }
      ]
    },
    {
      $set: {
        ...(input.title ? { title: input.title } : {}),
        ...(input.novelId ? { novelId: input.novelId } : {}),
        ...(input.authorId ? { authorId: input.authorId } : {}),
        content: input.content,
        wordCount: input.wordCount,
        lastAcceptedRevisionId: input.revisionId,
        lastAcceptedAt: input.acceptTimestamp,
        updatedAt: now
      },
      $inc: { version: 1 }
    }
  );


  if (result.matchedCount === 0 && existing) {
    return { status: 'skipped_newer_draft', draft: existing };
  }

  const updated = await findDraftChapterByChapterId(input.chapterId);
  return { status: 'synced', draft: updated };
}

export async function findDraftChapterByChapterId(chapterId: string) {
  return collection().findOne({ chapterId, deletedAt: null });
}

export async function markDraftChaptersDeletedByNovelId(novelId: string, reason: string | undefined) {
  const now = new Date();
  return collection().updateMany(
    { novelId, deletedAt: null },
    {
      $set: {
        deletedAt: now,
        deletionReason: reason ?? null,
        updatedAt: now
      }
    }
  );
}

export async function restoreDraftChaptersByNovelId(novelId: string) {
  const now = new Date();
  return collection().updateMany(
    { novelId, deletedAt: { $ne: null } },
    {
      $set: {
        deletedAt: null,
        deletionReason: null,
        restoredAt: now,
        updatedAt: now
      }
    }
  );
}
